// Build prompt dengan knowledge base context
const topic = $json.body.topic;
const audience = $json.body.audience || 'millennial';
const slideCount = $json.body.slideCount || 7;
const tone = $json.body.tone || 'casual';

// Knowledge base URLs di GitHub
const knowledgeBase = `
Knowledge Base Reference:
- Brand: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/01_LUMAKARA_BRAND_CHARACTER.md
- Services: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/02_LUMAKARA_SERVICES.md
- Topics: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/03_CONTENT_TOPICS_LIBRARY.md
- Calendar: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/04_INDONESIAN_CALENDAR_2026.md
- Strategy: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/05_CONTENT_STRATEGY.md
- Target Gen Z: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/06_TARGET_AUDIENCE_GEN_Z.md
- Target Millennial: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/07_TARGET_AUDIENCE_MILLENNIAL.md
- Target Gen X: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/08_TARGET_AUDIENCE_GEN_X.md
- Visual Guide: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/09_VISUAL_PROMPT_GUIDE.md
- Voice Examples: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/10_BRAND_VOICE_EXAMPLES.md
- Structure: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/11_CONTENT_STRUCTURE_GUIDE.md
- Character Rules: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/12_CHARACTER_COUNT_RULES.md
- PHP Format: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/13_PHP_OUTPUT_FORMAT.md
- Import Guide: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/14_IMPORT_INSTRUCTIONS.md
- Quality Checklist: https://raw.githubusercontent.com/lumakaraid/custom-ai/main/knowledge-base/15_QUALITY_CHECKLIST.md
`;

const systemPrompt = `Kamu adalah Lumakara Content Creator AI.

Baca dan ikuti semua guidelines dari knowledge base di GitHub (URLs di bawah).

${knowledgeBase}

Generate konten carousel Instagram untuk Lumakara dalam format PHP array sesuai 13_PHP_OUTPUT_FORMAT.md.

Pastikan:
- Brand voice konsisten (01_LUMAKARA_BRAND_CHARACTER.md)
- Sesuai target audience
- Character count rules (12_CHARACTER_COUNT_RULES.md)
- Include visual prompts (09_VISUAL_PROMPT_GUIDE.md)
- PHP syntax correct`;

const userPrompt = `Buatkan konten carousel Instagram tentang "${topic}" untuk target audience ${audience}, ${slideCount} slide.

Tone: ${tone}

Output dalam format PHP array yang bisa langsung di-import ke WordPress.`;

return {
  json: {
    systemPrompt,
    userPrompt,
    topic,
    audience,
    slideCount,
    tone
  }
};

// Extract content
const content = $json.choices[0].message.content;

// Generate filename
const date = new Date().toISOString().split('T')[0];
const topic = $('Prepare Prompt').item.json.topic.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '');
const filename = `${date}-${topic}.php`;

return {
  json: {
    success: true,
    filename,
    content,
    topic: $('Prepare Prompt').item.json.topic,
    audience: $('Prepare Prompt').item.json.audience,
    slideCount: $('Prepare Prompt').item.json.slideCount,
    generatedAt: new Date().toISOString()
  }
};
